import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.z3u3TMv0.js";const m=JSON.parse('{"title":"개인정보 처리방침","description":"MiniTavern Ultra 개인정보 안내 — 대화, 캐릭터, API Key는 기기 우선 저장; 전문은 공식 페이지.","frontmatter":{"title":"개인정보 처리방침","description":"MiniTavern Ultra 개인정보 안내 — 대화, 캐릭터, API Key는 기기 우선 저장; 전문은 공식 페이지.","head":[["meta",{"name":"keywords","content":"주점,AI 주점,MiniTavern,AI 파트너,AI 친구,AI 로컬 채팅,Silly Tavern,SillyTavern,모바일 Silly Tavern,Silly Tavern 모바일,Silly Tavern 안드로이드,Silly Tavern iOS,AI 롤플레이,캐릭터 카드,AI 채팅,모바일 AI,오프라인 AI,AI 스토리,로컬 LLM,Ollama,LM Studio,세계관,정규식,BYOK,사용자 가이드,매뉴얼"}],["meta",{"property":"og:title","content":"개인정보 처리방침 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern Ultra 개인정보 안내 — 대화, 캐릭터, API Key는 기기 우선 저장; 전문은 공식 페이지."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ko/privacy"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ko/privacy"}]]},"headers":[],"relativePath":"ko/privacy.md","filePath":"ko/privacy.md","lastUpdated":1787224147000}'),n={name:"ko/privacy.md"};function l(o,a,p,s,c,d){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="개인정보-처리방침" tabindex="-1">개인정보 처리방침 <a class="header-anchor" href="#개인정보-처리방침" aria-label="Permalink to &quot;개인정보 처리방침&quot;">​</a></h1><p><strong>MiniTavern Ultra는 개인정보를 소중히 합니다.</strong> 본 페이지는 데이터 처리 개요이며, 정식 법률 문구는 공식 개인정보 페이지를 따릅니다.</p><h2 id="기기-우선" tabindex="-1">기기 우선 <a class="header-anchor" href="#기기-우선" aria-label="Permalink to &quot;기기 우선&quot;">​</a></h2><p>기본 이용 방식에서 다음 데이터는 <strong>주로 기기에</strong> 저장되며, 채팅 내용으로서 MiniTavern 자체 업무 서버에 업로드되지 않습니다.</p><ul><li>대화 기록</li><li>개인화 설정과 환경설정</li><li>API Key（이용자가 입력·기기에 저장）</li><li>이용자가 만들거나 가져온 캐릭터 카드 및 관련 설정</li><li>월드북, 정규식, 페르소나 등 앱 내 설정</li></ul><p>백업 파일（예 <code>.tbk</code>）은 이용자가 내보내고 보관합니다. 키가 포함된 백업을 공유하지 마세요.</p><h2 id="byok와-제3자" tabindex="-1">BYOK와 제3자 <a class="header-anchor" href="#byok와-제3자" aria-label="Permalink to &quot;BYOK와 제3자&quot;">​</a></h2><p>제3자 또는 로컬 모델 서비스를 설정·호출할 때:</p><ul><li>요청은 <strong>이용자가 지정한</strong> API 주소（클라우드 벤더 또는 LAN의 Ollama / LM Studio 등）로 갑니다</li><li>해당 사업자는 자체 개인정보 정책에 따라 요청을 처리합니다</li><li>MiniTavern은 제3자를 대신해 프롬프트나 생성 결과에 대해 책임지지 않습니다</li></ul><h2 id="전문" tabindex="-1">전문 <a class="header-anchor" href="#전문" aria-label="Permalink to &quot;전문&quot;">​</a></h2><p>전체 개인정보 처리방침:</p><p><strong><a href="https://minitavern.github.io/ultra_privacy/" target="_blank" rel="noreferrer">개인정보 처리방침 전문</a></strong></p><p>문의: <a href="mailto:minitavern@gmail.com" target="_blank" rel="noreferrer">minitavern@gmail.com</a></p><p>관련: <a href="/ultra_guides/ko/terms">이용약관</a></p>',14)])])}const u=e(n,[["render",l]]);export{m as __pageData,u as default};
